import java.util.*;import java.util.function.Function;
public class TestMain{static final class Repo implements InventoryRepository{Map<String,Integer>stock=new HashMap<>(Map.of("a",5,"b",2));boolean inTx;int outside;public Integer get(String s){if(!inTx)outside++;return stock.get(s);}public void set(String s,int q){if(!inTx)outside++;stock.put(s,q);}public<T>T transaction(Function<InventoryRepository,T>w){Map<String,Integer>before=new HashMap<>(stock);inTx=true;try{return w.apply(this);}catch(RuntimeException e){stock=before;throw e;}finally{inTx=false;}}}
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}public static void main(String[]a){Repo r=new Repo();InventoryReservationService s=new InventoryReservationService(r);Map<String,Integer>req=new LinkedHashMap<>();req.put("a",2);req.put("b",1);Map<String,Integer>out=s.reserve(req);check(out.equals(Map.of("a",3,"b",1)),"result");check(r.stock.equals(out),"stock");check(req.equals(Map.of("a",2,"b",1)),"input");check(r.outside==0,"outside tx");try{out.put("x",1);throw new AssertionError();}catch(UnsupportedOperationException e){}Map<String,Integer>before=new HashMap<>(r.stock);try{s.reserve(Map.of("a",1,"b",99));throw new AssertionError();}catch(IllegalStateException e){}check(r.stock.equals(before),"rollback");System.out.println("OK");}}
